def nearest_axis_aligned_point(x, y, points):
 best_distance=10**18;answer=-1
 for index,(px,py) in enumerate(points):
  if px==x or py==y:
   distance=abs(px-x)+abs(py-y)
   if distance<best_distance:best_distance=distance;answer=index
 return answer

